  it('returns ToolResponse naming the missing required field and skips the executor', async () => {
    const registry = new ToolRegistry();
    let executorCallCount = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCallCount += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCallCount,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCallCount: 0,
      mentionsRequiredField: true,
    });
  });
});

